import React, { useEffect, useState } from 'react';
import './Hero.css';
import logoImg from '../purayida-krishi-logo-malayalam.png';
import { apiGet } from '../api';

const Hero = ({ language }) => {
  const [bgImage, setBgImage] = useState('/pbg.jpg');
  
  useEffect(() => {
    let ignore = false;
    (async () => {
      try {
        const data = await apiGet('/api/settings');
        if (!ignore && data?.heroBackgroundUrl) {
          setBgImage(data.heroBackgroundUrl);
        }
      } catch (_) {
        // Use default background if API fails
      }
    })();
    return () => { ignore = true; };
  }, []);
  
  const content = {
    en: {
      title: 'Purayidakrishi',
      subtitle: 'Homestead Agroecology',
      discover: 'Discover more:',
      boxes: ['Practice', 'Article', 'Direction']
    },
    ml: {
      title: 'പുരയിടകൃഷി',
      subtitle: 'Homestead Agroecology',
      discover: 'കൂടുതൽ അറിയുക:',
      boxes: ['പ്രാക്ടീസ്', 'ലേഖനം', 'ദിശ']
    }
  };

  return (
    <section id="home" className="hero" style={{'--hero-bg-image': `url(${bgImage})`}}>
      {/* Top left corner logo */}
      <div className="hero-corner-logo">
        <img src="/purayida-krishi-logo--white.png" alt="Purayidakrishi" className="corner-logo" />
      </div>
      
      <div className="container hero-stack">
        {/* Logo only (title and subtitle removed as requested) */}
        <div className="hero-brand">
          <img src={logoImg} alt="Purayidakrishi" className="hero-logo" />
        </div>

        {/* Three decorative circles */}
        <div className="hero-circles" aria-hidden="false">
          <span className="circle"><span className="circle-text">പുരയിടകൃഷി പ്രിയോഗിക പാങ്ങൾ</span></span>
          <span className="circle"><span className="circle-text">കൃഷിയിലെ ഞാറ്റുവേലകൾ</span></span>
          <span className="circle"><span className="circle-text">നാട്ടുവിളകളും വിത്തുകളും</span></span>
        </div>

        {/* Discover more section with 3 boxes */}
        <div className="discover">
          <h3 className="discover-title">{content[language].discover}</h3>
          <div className="discover-grid">
            <a href="#/practical/1" className="discover-box card">{content[language].boxes[0]}</a>
            <a href="#/practical/2" className="discover-box card">{content[language].boxes[1]}</a>
            <a href="#/practical/3" className="discover-box card">{content[language].boxes[2]}</a>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Hero;
