import React, { useEffect, useState } from 'react';
import './EnglishBlog.css';
import { apiGet } from '../api';

const EnglishBlog = () => {
  const [remotePosts, setRemotePosts] = useState([]);
  const [loading, setLoading] = useState(false);
  useEffect(() => {
    let ignore = false;
    (async () => {
      try {
        setLoading(true);
        const resp = await apiGet('/api/posts', { locale: 'en' });
        const arr = Array.isArray(resp?.items) ? resp.items : [];
        if (!ignore) {
          const mapped = arr.map((p) => ({
            id: p.id,
            title: p.title,
            excerpt: p.excerpt || '',
            date: p.date,
            category: p.category?.slug || 'post',
            image: p.imageUrl || undefined,
            type: p.isAd ? 'ad' : 'post',
            adText: p.adText || undefined,
            ctaText: p.ctaText || undefined,
            slug: p.slug || undefined,
          }));
          setRemotePosts(mapped.filter((m) => m.title));
        }
      } catch (_) {}
      finally { setLoading(false); }
    })();
    return () => { ignore = true; };
  }, []);
  const content = {
    title: 'Agroecology for Organic',
    subtitle: 'This blog focuses on Agroecology and Organic Farming, highlighting practices, biodiversity, soil health, seed conservation, and related policies for climate-resilient farming systems.',
    readMore: 'Read More'
  };

  const postsToShow = remotePosts;
  return (
    <section id="english-blog" className="english-blog-section">
      <div className="container">
        <div className="english-blog-header">
          <h2 className="english-blog-title">{content.title}</h2>
          <p className="english-blog-subtitle">{content.subtitle}</p>
        </div>

        <div className="english-blog-grid">
          {postsToShow.map((post) => (
            <article key={post.id} className={`english-blog-card ${post.type === 'ad' ? 'english-blog-card-ad' : ''}`}>
              <div className="english-blog-image">
                <img 
                  src={post.image} 
                  alt={post.title}
                  onError={(e) => {
                    e.target.src = `https://via.placeholder.com/400x250/2d5016/ffffff?text=${encodeURIComponent(post.category)}`;
                  }}
                />
                <div className={`english-blog-category ${post.type === 'ad' ? 'english-blog-category-ad' : ''}`}>
                  {post.type === 'ad' && post.adText && (
                    <span className="english-ad-label">{post.adText}</span>
                  )}
                  {post.category}
                </div>
              </div>
              
              <div className="english-blog-content">
                {post.type === 'post' && (
                  <div className="english-blog-meta">
                    <span className="english-blog-date">{post.date}</span>
                  </div>
                )}
                
                <h3 className="english-blog-post-title">{post.title}</h3>
                <p className="english-blog-excerpt">{post.excerpt}</p>
                
                <button
                  className={`english-blog-read-more ${post.type === 'ad' ? 'english-blog-cta-button' : ''}`}
                  onClick={() => {
                    if (post.type === 'post' && post.slug) {
                      window.scrollTo(0, 0);
                      window.location.hash = `#/blog/en/${post.slug}`;
                    }
                  }}
                >
                  {post.type === 'ad' ? post.ctaText : content.readMore}
                  <svg className="english-read-more-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                  </svg>
                </button>
              </div>
            </article>
          ))}
        </div>

        <div className="english-blog-footer">
          <button className="english-view-all-posts" onClick={() => { window.scrollTo(0, 0); window.location.hash = '#/blog/en'; }}>
            View All English Posts
          </button>
          {postsToShow.length === 0 && !loading && (
            <div style={{ textAlign: 'center', color: '#6b7280', marginTop: 8 }}>No posts found.</div>
          )}
        </div>
      </div>
    </section>
  );
};

export default EnglishBlog;
