import React, { useEffect, useState } from 'react';
import './Ads.css';
import { apiGet } from '../api';

const RightAd = ({ language = 'en' }) => {
  const [ads, setAds] = useState([]);

  useEffect(() => {
    let ignore = false;
    (async () => {
      try {
        const resp = await apiGet('/api/posts', { locale: language, isAd: true, placement: 'blog_all', limit: 3 });
        const items = Array.isArray(resp?.items) ? resp.items : [];
        if (!ignore) setAds(items);
      } catch (_) {
        if (!ignore) setAds([]);
      }
    })();
    return () => { ignore = true; };
  }, [language]);

  return (
    <aside className="ad-right" role="complementary" aria-label="Right Sidebar Advertisement">
      {ads.length === 0 ? (
        <div className="ad-label">Display your Ads here</div>
      ) : (
        <div className="ad-right-list">
          {ads.map((ad) => (
            <a key={ad.id} href={ad.ctaUrl || '#'} target={ad.ctaUrl ? '_blank' : undefined} rel={ad.ctaUrl ? 'noopener noreferrer' : undefined} className="ad-card">
              <img src={ad.imageUrl || 'https://via.placeholder.com/300x200/2d5016/ffffff?text=Advertisement'} alt={ad.title || 'Advertisement'} />
              <div className="ad-card-body">
                {ad.adText && <span className="ad-label">{ad.adText}</span>}
                <div className="ad-card-title">{ad.title}</div>
                {ad.ctaText && <div className="ad-card-cta">{ad.ctaText}</div>}
              </div>
            </a>
          ))}
        </div>
      )}
    </aside>
  );
};

export default RightAd;
