import React, { useEffect, useState } from 'react';
import './Ads.css';
import { apiGet } from '../api';

const BottomAd = ({ language = 'en' }) => {
  const [ad, setAd] = useState(null);

  useEffect(() => {
    let ignore = false;
    (async () => {
      try {
        const resp = await apiGet('/api/posts', { locale: language, isAd: true, placement: 'home', limit: 1 });
        const items = Array.isArray(resp?.items) ? resp.items : [];
        if (!ignore) setAd(items[0] || null);
      } catch (_) {
        if (!ignore) setAd(null);
      }
    })();
    return () => { ignore = true; };
  }, [language]);

  return (
    <div className="ad-bottom" role="complementary" aria-label="Bottom Advertisement">
      {ad ? (
        <a href={ad.ctaUrl || '#'} target={ad.ctaUrl ? '_blank' : undefined} rel={ad.ctaUrl ? 'noopener noreferrer' : undefined} className="ad-bottom-inner">
          <img src={ad.imageUrl || 'https://via.placeholder.com/1200x240/2d5016/ffffff?text=Advertisement'} alt={ad.title || 'Advertisement'} />
          <div className="ad-bottom-content">
            {ad.adText && <span className="ad-label">{ad.adText}</span>}
            <div className="ad-bottom-title">{ad.title}</div>
            {ad.ctaText && <div className="ad-bottom-cta">{ad.ctaText}</div>}
          </div>
        </a>
      ) : (
        <div className="ad-label">Display Your ads here</div>
      )}
    </div>
  );
};

export default BottomAd;
