import React, { useEffect, useState } from 'react';
import { apiGet } from '../api';
import '../components/Gallery.css';

export default function GalleryPage({ language = 'en' }) {
  const [sets, setSets] = useState([]);
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    let ignore = false;
    (async () => {
      setLoading(true);
      setError('');
      try {
        const groups = await apiGet('/api/gallery-sets', { locale: language });
        const valid = Array.isArray(groups) ? groups.filter((g) => Array.isArray(g.images) && g.images.length > 0) : [];
        if (!ignore && valid.length) {
          setSets(valid);
          setItems([]);
          setLoading(false);
          return;
        }
      } catch (_) {
        // fall through to images
      }
      try {
        const data = await apiGet('/api/gallery-images', { locale: language, sort: 'order:asc' });
        if (!ignore && Array.isArray(data)) {
          setItems(data);
          setSets([]);
        }
      } catch (e) {
        if (!ignore) setError('Failed to load gallery');
      } finally {
        if (!ignore) setLoading(false);
      }
    })();
    return () => { ignore = true; };
  }, [language]);

  const getYouTubeThumbnail = (url) => {
    const videoId = url && url.match(/(?:youtube\.com\/(?:[^\/]+\/.+\/|(?:v|e(?:mbed)?)\/|.*[?&]v=)|youtu\.be\/)([^"&?\/ ]{11})/);
    return (videoId && videoId[1]) ? `https://img.youtube.com/vi/${videoId[1]}/maxresdefault.jpg` : null;
  };

  const open = (url) => window.open(url, '_blank');

  return (
    <section className="section" style={{ paddingTop: 24 }}>
      <div className="container">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <h2 style={{ margin: 0 }}>{language === 'en' ? 'Gallery' : 'ഗാലറി'}</h2>
          <a href="#" className="btn btn-secondary">{language === 'en' ? 'Back to Home' : 'ഹോം'}</a>
        </div>

        {loading && (
          <div style={{ textAlign: 'center', color: '#6b7280', padding: '2rem 0' }}>
            {language === 'en' ? 'Loading...' : 'ലോഡിംഗ്...'}
          </div>
        )}
        {error && (
          <div style={{ textAlign: 'center', color: '#b91c1c', padding: '1rem 0' }}>{error}</div>
        )}

        {/* Grouped view */}
        {(!loading && !error && sets.length > 0) && sets.map((group) => (
          <div key={group.id} className="card" style={{ padding: 16, marginBottom: 16 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', marginBottom: 12 }}>
              <div>
                <h3 style={{ margin: 0 }}>{group.title || `${language === 'en' ? 'Set' : 'സെറ്റ്'} #${group.id}`}</h3>
                {group.date && <div style={{ color: '#64748b', fontSize: 13 }}>{new Date(group.date).toLocaleDateString()}</div>}
              </div>
              <div style={{ color: '#64748b', fontSize: 13 }}>{group.images.length} {language === 'en' ? 'items' : 'ഇനങ്ങൾ'}</div>
            </div>
            <div className="gallery-grid">
              {group.images.map((it, idx) => {
                const type = it.type || (it.youtubeUrl ? 'youtube' : (it.videoUrl ? 'video' : 'image'));
                const thumb = type === 'youtube' ? (getYouTubeThumbnail(it.youtubeUrl) || it.imageUrl) : it.imageUrl;
                return (
                  <div key={it.id || idx} className="gallery-item" onClick={() => open(it.imageUrl || it.videoUrl || it.youtubeUrl)}>
                    {type === 'youtube' ? (
                      <img src={thumb} alt={it.caption || ''} />
                    ) : type === 'video' ? (
                      <div className="video-placeholder">{language === 'en' ? 'Video' : 'വീഡിയോ'}</div>
                    ) : (
                      <img src={thumb} alt={it.caption || ''} />
                    )}
                    {(it.caption || it.description) && (
                      <div className="gallery-caption">
                        <div className="caption-text">{it.caption || ''}</div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {/* Flat view */}
        {(!loading && !error && sets.length === 0) && (
          <div className="card" style={{ padding: 16 }}>
            <div className="gallery-grid">
              {items.map((it, idx) => {
                const type = it.type || (it.youtubeUrl ? 'youtube' : (it.videoUrl ? 'video' : 'image'));
                const thumb = type === 'youtube' ? (getYouTubeThumbnail(it.youtubeUrl) || it.imageUrl) : it.imageUrl;
                return (
                  <div key={it.id || idx} className="gallery-item" onClick={() => open(it.imageUrl || it.videoUrl || it.youtubeUrl)}>
                    {type === 'youtube' ? (
                      <img src={thumb} alt={it.caption || ''} />
                    ) : type === 'video' ? (
                      <div className="video-placeholder">{language === 'en' ? 'Video' : 'വീഡിയോ'}</div>
                    ) : (
                      <img src={thumb} alt={it.caption || ''} />
                    )}
                    {(it.caption || it.description) && (
                      <div className="gallery-caption">
                        <div className="caption-text">{it.caption || ''}</div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {(!loading && !error && sets.length === 0 && items.length === 0) && (
          <div style={{ textAlign: 'center', color: '#6b7280', padding: '2rem 0' }}>
            {language === 'en' ? 'No gallery items found.' : 'ഗാലറി ഇനങ്ങൾ ലഭ്യമല്ല.'}
          </div>
        )}
      </div>
    </section>
  );
}
