import React, { useEffect, useState } from 'react';
import './Agroecology.css';
import logoEng from '../purayida-krishi-logo-eng.png';
import { apiGet } from '../api';

const Agroecology = () => {
  const [bgImage, setBgImage] = useState('/agrobg.jpg');
  
  useEffect(() => {
    let ignore = false;
    (async () => {
      try {
        const data = await apiGet('/api/settings');
        if (!ignore && data?.agroecologyBackgroundUrl) {
          setBgImage(data.agroecologyBackgroundUrl);
        }
      } catch (_) {
        // Use default background if API fails
      }
    })();
    return () => { ignore = true; };
  }, []);
  
  return (
    <section id="agroecology" className="section agro" style={{'--agro-bg-image': `url(${bgImage})`}}>
      {/* Top left corner logo */}
      <div className="agro-corner-logo">
        <img src="/purayida-krishi-logo--white.png" alt="Purayidakrishi" className="corner-logo" />
      </div>

      <div className="container">
        <div className="agro-title">
          <img src={logoEng} alt="Purayidakrishi" className="agro-logo" />
        </div>

        {/* Row of 3 circles with text 'benifits' */}
        <div className="agro-circles">
          <span className="agro-circle"><span className="agro-circle-text">Agroecology for Organic</span></span>
          <span className="agro-circle"><span className="agro-circle-text">Traditional Farming practices</span></span>
          <span className="agro-circle"><span className="agro-circle-text">Seed Conservation</span></span>
        </div>

        {/* Row of 3 boxes with text 'practce' */}
        <div className="agro-grid">
          <div className="agro-box card">practce</div>
          <div className="agro-box card">practce</div>
          <div className="agro-box card">practce</div>
        </div>
      </div>
    </section>
  );
};

export default Agroecology;
